part of 'sanitizer.dart';

/// A banner states the file's origin at the start of a comment line, past any
/// `WARNING:`, `BEGIN` or `DO NOT EDIT.` lead-in or a run of decoration; a
/// single `-` or `*` opens a bullet, which is prose. Stated outright
/// (`This file is generated`, `This is a generated file`) anything may follow.
/// Otherwise the next word or the punctuation must show it is the banner
/// (`Generated by`, not `Generated tokens`; `Generated code.`, not
/// `Generated code helpers` or `generated.dart`).
/// `It is generated` counts only after a `do not edit` sentence: alone it
/// continues a sentence about something else.
final _generatedBanner = RegExp(
  r'^(?:([*=-])\1+\s*)?[@<]?'
  r'(?:(?:warning|note)\s*[:-]+\s*)?'
  r'(?:begin\s+)?'
  r"(?:(?:do\s+not|don['’]?t)\s+(?:edit|modify)\b[^.!:]*[.,:!-]+\s*"
  r"(?:(?:it|the\s+(?:code|file))(?:['’]s|\s+is|\s+was)\s+)?)?(?:"
  r'this\s+(?:file|code)\s+(?:is|was|has\s+been)\s+'
  r'(?:auto(?:matically)?[-\s]?)?generated\b'
  r'|this\s+is\s+(?:an?\s+)?(?:auto(?:matically)?[-\s]?)?generated\s+'
  r'(?:code|file)\b'
  r'|(?:this\s+is\s+)?(?:(?:code|file|mocks)\s+)?'
  r'(?:auto(?:matically)?[-\s]?)?generated(?:\s+automatically\b|'
  r'(?:\s+(?:code|file))?'
  r'(?:\s+(?:by|from|using|with|via)\b'
  r'|\s*(?:$|[.!:;](?=\s|$)|,\s*do\s+not\b|[*=]{2,}|/?>)'
  r'|\s+[-–—]|\s+do\s+not\b))'
  ')',
  caseSensitive: false,
);

/// A line that ends a sentence, so the next one starts afresh: an ellipsis does
/// not.
final _sentenceEnd = RegExp(r'(?<!\.\.)[.!?:;]$');

/// A header line that is no sentence, so the next line cannot continue it:
/// decoration or a tool's directive. `// Copyright 2026 ACME` is not one of
/// these: a lowercase line after it reads as its continuation.
final _notProse = RegExp(
  r'^(?:[^a-z.]*$|!|-\*-|@dart\b|ignore(?:_for_file)?:|coverage:|'
  r'dart\s+format\b|spdx-)',
  caseSensitive: false,
);

final _commentMarkers = RegExp(r'^[/#\s]+');
final _blockGutter = RegExp(r'^\s*\*(?!\*)\s*');
final _lowercaseStart = RegExp('^[a-z]');

/// Generated-code filter: the file's leading comment says so (build_runner,
/// FlutterFire, intl, mockito, pigeon, protoc, slang). Filename shape
/// (`*.g.dart` vs a handwritten `*.preview.dart`) proves nothing, the header
/// does.
bool _isGeneratedFile(String path) {
  final file = File(path);
  if (!file.existsSync()) return false;
  final RandomAccessFile raf;
  try {
    raf = file.openSync();
  } on FileSystemException {
    return false;
  }
  try {
    var chunk = 4096;
    final bytes = <int>[];
    var eof = false;
    var text = '';
    void readMore() {
      if (eof) return;
      final next = raf.readSync(chunk);
      if (next.length < chunk) eof = true;
      chunk *= 2;
      bytes.addAll(next);
      final raw = utf8.decode(bytes, allowMalformed: true);
      text = raw.startsWith('\uFEFF') ? raw.substring(1) : raw;
    }

    readMore();
    String lineFrom(int start) {
      var end = text.indexOf('\n', start);
      while (end == -1 && !eof) {
        readMore();
        end = text.indexOf('\n', start);
      }
      return text.substring(start, end == -1 ? text.length : end);
    }

    int blockClose(int start) {
      var close = text.indexOf('*/', start);
      while (close == -1 && !eof) {
        readMore();
        close = text.indexOf('*/', start);
      }
      return close;
    }

    var previous = '';
    bool opensBanner(String line) {
      final continues =
          previous.isNotEmpty &&
          !_sentenceEnd.hasMatch(previous) &&
          !_notProse.hasMatch(previous) &&
          _lowercaseStart.hasMatch(line);
      previous = line;
      return !continues && _generatedBanner.hasMatch(line);
    }

    var docDecided = false;
    var i = 0;
    while (true) {
      var newlines = 0;
      while (true) {
        if (i + 4 > text.length && !eof) readMore();
        if (i < text.length && text[i].trim().isEmpty) {
          if (text[i] == '\n') newlines++;
          i++;
        } else {
          break;
        }
      }
      if (newlines > 1) previous = '';
      if (text.startsWith('///', i)) {
        final line = lineFrom(i);
        final doc = line.replaceFirst(_commentMarkers, '').trim();
        if (doc.isNotEmpty) {
          if (!docDecided && _generatedBanner.hasMatch(doc)) return true;
          docDecided = true;
          previous = doc;
        }
        i += line.length;
        continue;
      }
      if (text.startsWith('/**', i) && !text.startsWith('/**/', i)) {
        final close = blockClose(i + 3);
        final body = text.substring(i + 3, close == -1 ? text.length : close);
        for (final line in body.split('\n')) {
          final doc = line.replaceFirst(_blockGutter, '').trim();
          if (doc.isNotEmpty) return _generatedBanner.hasMatch(doc);
        }
        return false;
      }
      if (text.startsWith('//', i) || text.startsWith('#', i)) {
        final line = lineFrom(i);
        if (opensBanner(line.replaceFirst(_commentMarkers, '').trim())) {
          return true;
        }
        i += line.length;
        continue;
      }
      if (text.startsWith('/*', i)) {
        final close = blockClose(i + 2);
        final body = text.substring(i + 2, close == -1 ? text.length : close);
        for (final line in body.split('\n')) {
          if (opensBanner(line.replaceFirst(_blockGutter, '').trim())) {
            return true;
          }
        }
        if (close == -1) return false;
        i = close + 2;
        continue;
      }
      return false;
    }
  } finally {
    raf.closeSync();
  }
}
